DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_reconciliation_rows(uuid,date)'::regprocedure) INTO def;def:=replace(def,'public.finance_reconciliation_rows(', 'public.finance_reconciliation_base_rows(');EXECUTE def;END $$;REVOKE ALL ON FUNCTION public.finance_reconciliation_base_rows(uuid,date) FROM PUBLIC;
CREATE OR REPLACE FUNCTION public.finance_reconciliation_rows(p_tenant uuid,p_month date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb;r record;gl numeric;detail numeric;items jsonb;diff numeric;snapshot text;why text;ending date:=(date_trunc('month',p_month)+interval '1 month -1 day')::date;stock_on boolean;BEGIN result:=finance_reconciliation_base_rows(p_tenant,p_month);SELECT stock_basis='counts' INTO stock_on FROM finance_schedule_settings WHERE tenant_id=p_tenant;
FOR r IN SELECT * FROM (VALUES ('fixed_assets','Fixed assets',ARRAY['1500','1510','1520','1530','1540','1550']),('prepayments','Prepayments',ARRAY['1320']),('accruals','Accruals',ARRAY['2200']),('deposits','Deposits paid',ARRAY['1310','1330']),('deferred','Deferred revenue',ARRAY['2300']),('grni','Goods received not invoiced',ARRAY['2210']),('stock','Stock',ARRAY['1400']),('tax','Tax payable',ARRAY['2350'])) AS v(key,name,codes) LOOP IF r.key='stock' AND NOT coalesce(stock_on,false) THEN CONTINUE;END IF;
SELECT coalesce(sum(l.debit-l.credit),0) INTO gl FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id JOIN chart_of_accounts a ON a.id=l.account_id WHERE e.tenant_id=p_tenant AND e.status='posted' AND e.entry_date<=ending AND a.code=ANY(r.codes);IF r.key IN('accruals','deferred','grni','tax') THEN gl:=-gl;END IF;detail:=0;items:='[]';
IF r.key='fixed_assets' THEN SELECT coalesce(sum(cost-amount_depreciated),0),coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'date',in_service_date,'amount',cost-amount_depreciated,'href','/finance/books?view=schedules')),'[]') INTO detail,items FROM fixed_assets WHERE tenant_id=p_tenant AND in_service_date<=ending AND status<>'disposed';
ELSIF r.key='prepayments' THEN SELECT coalesce(sum(total_amount-coalesce((SELECT sum(planned_amount) FROM prepaid_schedule_lines WHERE schedule_id=s.id AND status='posted' AND period<=ending),0)),0),coalesce(jsonb_agg(jsonb_build_object('id',id,'name',description,'date',start_period,'amount',amount_remaining,'href','/finance/books?view=schedules')),'[]') INTO detail,items FROM prepaid_schedules s WHERE tenant_id=p_tenant AND start_period<=ending AND status='active';
ELSIF r.key='accruals' THEN SELECT coalesce(sum(amount),0),coalesce(jsonb_agg(jsonb_build_object('id',id,'name',reason,'date',month_start,'amount',amount,'href','/finance/books?view=schedules')),'[]') INTO detail,items FROM expense_accrual_drafts WHERE tenant_id=p_tenant AND month_start<=ending AND journal_entry_id IS NOT NULL AND reversal_entry_id IS NULL;
ELSIF r.key='deferred' THEN SELECT coalesce(sum(amount-used_amount),0),coalesce(jsonb_agg(jsonb_build_object('id',id,'name',reference||' · '||guest_event,'date',issued_date,'amount',amount-used_amount,'href','/finance/books?view=schedules')),'[]') INTO detail,items FROM finance_deferred_items WHERE tenant_id=p_tenant AND issued_date<=ending AND status IN('active','closed');
ELSIF r.key='deposits' THEN SELECT coalesce(sum(total_value),0),coalesce(jsonb_agg(jsonb_build_object('id',id,'name',description,'date',as_of_date,'amount',total_value,'href','/finance/books?view=schedules')),'[]') INTO detail,items FROM deposit_opening_balances WHERE tenant_id=p_tenant AND as_of_date<=ending;
ELSIF r.key='grni' THEN SELECT coalesce(sum(i.quantity_received*i.unit_cost),0) INTO detail FROM goods_received_notes g JOIN grn_items i ON i.grn_id=g.id WHERE g.tenant_id=p_tenant AND g.received_date<=ending AND g.invoice_id IS NULL AND g.status IN('received','approved','completed');
ELSIF r.key='stock' THEN SELECT coalesce(sum(i.counted_qty*i.unit_cost),0) INTO detail FROM stock_count_items i JOIN (SELECT DISTINCT ON(venue) id FROM stock_count_sessions WHERE tenant_id=p_tenant AND status='approved' AND count_date<=ending ORDER BY venue,count_date DESC) c ON c.id=i.session_id;
ELSIF r.key='tax' THEN SELECT coalesce(sum((d.source_data->>'target_tax')::numeric),0) INTO detail FROM finance_entry_drafts d WHERE tenant_id=p_tenant AND kind='tax' AND status='approved' AND entry_date=(SELECT max(entry_date) FROM finance_entry_drafts WHERE tenant_id=p_tenant AND kind='tax' AND status='approved' AND entry_date<=ending);END IF;
diff:=round(detail-gl,2);snapshot:=md5(jsonb_build_object('key',r.key,'month',p_month,'books',gl,'detail',detail,'items',items)::text);SELECT reason INTO why FROM finance_reconciliation_explanations WHERE tenant_id=p_tenant AND month_start=date_trunc('month',p_month)::date AND reconciliation_key=r.key AND finance_reconciliation_explanations.snapshot=snapshot ORDER BY created_at DESC LIMIT 1;
result:=result||jsonb_build_array(jsonb_build_object('key',r.key,'name',r.name,'books',gl,'detail',detail,'difference',diff,'note','Register items versus posted account balance; missing evidence is not guessed.','state',CASE WHEN abs(diff)<0.005 THEN 'agrees' ELSE 'open' END,'snapshot',snapshot,'reason',why,'items',items));END LOOP;RETURN result;END $$;REVOKE ALL ON FUNCTION public.finance_reconciliation_rows(uuid,date) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_reconciliation_rows(uuid,date) TO authenticated;